(601519, 61223, 12475, '<td valign="top">I see a tired family; this scene has potential but this is too snapshotty to fulfill it.</td>', 'I see a tired family; this scene has potential but this is too snapshotty to fulfill it.', '2004-02-27 15:44:42.000000', NULL, 1),
(601521, 61912, 14593, '<td valign="top">this is a nice photo.....I like the composition and the water action too.....I almost wondered how it looked in color, but I gather the skys were very gray and overcast......</td>', 'this is a nice photo.....I like the composition and the water action too.....I almost wondered how it looked in color, but I gather the skys were very gray and overcast......', '2004-02-27 15:45:55.000000', NULL, 1),
